# 分镜：每一句口播对应一镜（或拆成几镜，或用 '+' 并进上一镜）。build.py 读它，按口播实际时长排时间轴。
# V(种类, 镜头, 物, 动作, 屏上字, 镜头参数, **画面参数)
def V(k, cam, obj, verb, txt='', cp=None, w=1.0, **p):
    return {'k': k, 'cam': cam, 'cp': cp or {}, 'obj': obj, 'verb': verb, 'txt': txt, 'p': p, 'w': w}

NAMES = {10: 'curry', 9: 'shaq', 8: 'duncan', 7: 'bird', 6: 'wilt', 5: 'russell', 4: 'magic', 3: 'kareem', 2: 'lebron', 1: 'jordan'}
PLATE = {'curry': 'CURRY', 'shaq': "O'NEAL", 'duncan': 'DUNCAN', 'bird': 'BIRD', 'wilt': 'WILT', 'russell': 'RUSSELL',
         'magic': 'MAGIC', 'kareem': 'KAREEM', 'lebron': 'JAMES', 'jordan': 'JORDAN'}
def lx(r): return 960 + (10 - r - 4.5) * 178
def LK(ranks=(), new=None, at=0.4, **kw):
    """更衣柜：ranks 已挂好；new = 这一镜要挂进去的那一个（at 秒时落下、铭牌随后刻上）"""
    f, pl = {}, {}
    for r in ranks: f[r] = NAMES[r]; pl[r] = {'text': PLATE[NAMES[r]]}
    if new:
        f[new] = {'id': NAMES[new], 'at': at}; pl[new] = {'text': PLATE[NAMES[new]], 'at': at + 0.9}
    d = dict(filled=f, plates=pl); d.update(kw); return d
def C_(kind, **kw): return (kind, kw)
ALL = list(range(10, 0, -1))
J = lambda who, **kw: dict(who=who, **kw)

